arguments.command:
python3 -c "
# Check available packages for gene ID mapping
try:
    import mygene
    print('mygene available')
except:
    print('mygene not available')

try:
    import requests
    print('requests available')
except:
    print('requests not available')

# Check for any mapping files
import os
for f in os.listdir('.'):
    if any(x in f.lower() for x in ['gene', 'map', 'symbol', 'refseq', 'convert']):
        print(f'Found: {f}')
"

